import heapq
from collections import defaultdict

def CalculateLatestArrivalTimes(N, M, train_info):
    graph = [[] for _ in range(N)]
    for l, d, k, c, A, B in train_info:
        A -= 1
        B -= 1
        graph[B].append((A, l, d, k, c))

    inf = float('inf')
    time = [-inf] * N
    time[N-1] = inf
    queue = [(inf, N-1)]

    while queue:
        tx, x = heapq._heappop_max(queue)
        if time[x] >= tx:
            continue
        time[x] = tx
        for y, l, d, k, c in graph[x]:
            if tx < l + c:
                continue
            if l + (k - 1) * d + c <= tx:
                ty = l + (k - 1) * d
            else:
                ty = tx - (tx - c - l) % d
            if time[y] < ty:
                time[y] = ty
                heapq._heappush_max(queue, (ty, y))

    result = []
    for i in range(N-1):
        ans = time[i]
        if ans == -inf:
            ans = "Unreachable"
        result.append(ans)

    return result
